from bisect import bisect_left

class Solution:
    def maximumSumQueries(self, nums1: list[int], nums2: list[int], queries: list[list[int]]) -> list[int]:
        pairs = sorted(zip(nums1, nums2), key=lambda x: x[0], reverse=True)
        q_sorted = sorted([(qx, qy, i) for i, (qx, qy) in enumerate(queries)], key=lambda x: x[0], reverse=True)
        ans = [-1] * len(queries)
        stack = []
        p = 0
        n = len(pairs)
        for qx, qy, qidx in q_sorted:
            while p < n and pairs[p][0] >= qx:
                x, y = pairs[p]
                s = x + y
                while stack and stack[-1][1] <= s:
                    stack.pop()
                if not stack or stack[-1][0] < y:
                    stack.append((y, s))
                p += 1
            idx = bisect_left(stack, (qy, -1))
            if idx < len(stack):
                ans[qidx] = stack[idx][1]
        return ans

class Solution {
public:
    vector<int> maximumSumQueries(vector<int>& nums1, vector<int>& nums2, vector<vector<int>>& queries) {
        int n = nums1.size();
        vector<pair<int, int>> pairs(n);
        for (int i = 0; i < n; ++i) pairs[i] = {nums1[i], nums2[i]};
        sort(pairs.begin(), pairs.end(), [](const auto& a, const auto& b) {
            return a.first > b.first;
        });
        int q = queries.size();
        vector<tuple<int, int, int>> q_sorted(q);
        for (int i = 0; i < q; ++i) q_sorted[i] = {queries[i][0], queries[i][1], i};
        sort(q_sorted.begin(), q_sorted.end(), [](const auto& a, const auto& b) {
            return get<0>(a) > get<0>(b);
        });
        vector<int> ans(q, -1);
        vector<pair<int, int>> stack;
        int p = 0;
        for (const auto& [qx, qy, qidx] : q_sorted) {
            while (p < n && pairs[p].first >= qx) {
                int x = pairs[p].first, y = pairs[p].second;
                int s = x + y;
                while (!stack.empty() && stack.back().second <= s) {
                    stack.pop_back();
                }
                if (stack.empty() || stack.back().first < y) {
                    stack.push_back({y, s});
                }
                p++;
            }
            int l = 0, r = stack.size() - 1, best = -1;
            while (l <= r) {
                int mid = l + (r - l) / 2;
                if (stack[mid].first >= qy) {
                    best = mid;
                    r = mid - 1;
                } else {
                    l = mid + 1;
                }
            }
            if (best != -1) ans[qidx] = stack[best].second;
        }
        return ans;
    }
};

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

class Solution {
    public int[] maximumSumQueries(int[] nums1, int[] nums2, int[][] queries) {
        int n = nums1.length;
        int[][] pairs = new int[n][2];
        for (int i = 0; i < n; i++) {
            pairs[i][0] = nums1[i];
            pairs[i][1] = nums2[i];
        }
        Arrays.sort(pairs, (a, b) -> Integer.compare(b[0], a[0]));
        int q = queries.length;
        Integer[] qIdx = new Integer[q];
        for (int i = 0; i < q; i++) qIdx[i] = i;
        Arrays.sort(qIdx, (a, b) -> Integer.compare(queries[b][0], queries[a][0]));
        int[] ans = new int[q];
        Arrays.fill(ans, -1);
        List<int[]> stack = new ArrayList<>();
        int p = 0;
        for (int idx : qIdx) {
            int qx = queries[idx][0], qy = queries[idx][1];
            while (p < n && pairs[p][0] >= qx) {
                int x = pairs[p][0], y = pairs[p][1];
                int s = x + y;
                while (!stack.isEmpty() && stack.get(stack.size() - 1)[1] <= s) {
                    stack.remove(stack.size() - 1);
                }
                if (stack.isEmpty() || stack.get(stack.size() - 1)[0] < y) {
                    stack.add(new int[]{y, s});
                }
                p++;
            }
            int l = 0, r = stack.size() - 1, best = -1;
            while (l <= r) {
                int mid = l + (r - l) / 2;
                if (stack.get(mid)[0] >= qy) {
                    best = mid;
                    r = mid - 1;
                } else {
                    l = mid + 1;
                }
            }
            if (best != -1) ans[idx] = stack.get(best)[1];
        }
        return ans;
    }
}

var maximumSumQueries = function(nums1, nums2, queries) {
    const n = nums1.length;
    const pairs = [];
    for (let i = 0; i < n; i++) pairs.push([nums1[i], nums2[i]]);
    pairs.sort((a, b) => b[0] - a[0]);
    const q = queries.length;
    const qIdx = Array.from({ length: q }, (_, i) => i);
    qIdx.sort((a, b) => queries[b][0] - queries[a][0]);
    const ans = new Array(q).fill(-1);
    const stack = [];
    let p = 0;
    for (const idx of qIdx) {
        const [qx, qy] = queries[idx];
        while (p < n && pairs[p][0] >= qx) {
            const [x, y] = pairs[p];
            const s = x + y;
            while (stack.length > 0 && stack[stack.length - 1][1] <= s) {
                stack.pop();
            }
            if (stack.length === 0 || stack[stack.length - 1][0] < y) {
                stack.push([y, s]);
            }
            p++;
        }
        let l = 0, r = stack.length - 1, best = -1;
        while (l <= r) {
            const mid = Math.floor((l + r) / 2);
            if (stack[mid][0] >= qy) {
                best = mid;
                r = mid - 1;
            } else {
                l = mid + 1;
            }
        }
        if (best !== -1) ans[idx] = stack[best][1];
    }
    return ans;
};
